css:
/* Photo tiles: a photo with a caption and a button underneath, three to a row. Photos, captions and buttons are fields on the placement. */
.bz-section[data-bz-node="pt"]{padding-block:clamp(40px,4vw,64px)}
[data-bz-node="pt"] .bz-block{padding-block:0}
[data-bz-node="pt-row"]{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(20px,2.4vw,32px);align-items:start}
[data-bz-node="pt-row"]>.bz-col{grid-column:auto;width:auto;max-width:none;padding:0}
[data-bz-node^="pt-img"] img{display:block;aspect-ratio:4/3;width:100%;height:auto;object-fit:cover;border-radius:0}
[data-bz-node^="pt-img"] figcaption{margin-top:8px;font:700 .625rem/1.4 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--muted,#6b6a66)}
[data-bz-node^="pt-btn"]{margin-top:var(--space-3)}
[data-bz-node^="pt-btn"] .bz-btns{margin:0}
[data-bz-node^="pt-btn"] .bz-btn{width:100%}
@media (max-width:900px){[data-bz-node="pt-row"]{grid-template-columns:minmax(0,1fr)}}
